368	+public class DataSetLockManager implements DataNodeLockManager<AutoCloseDataSetLock> {
369	+  public static final Log LOG = LogFactory.getLog(DataSetLockManager.class);
370	+  private final HashMap<String, TrackLog> threadCountMap = new HashMap<>();
371	+  private final LockMap lockMap = new LockMap();
372	+  private boolean isFair = true;
373	+  private final boolean openLockTrace;
