376	+  /**
377	+   * Class for maintain lockMap and is thread safe.
378	+   */
379	+  private class LockMap {
380	+    private final HashMap<String, AutoCloseDataSetLock> readlockMap = new HashMap<>();
381	+    private final HashMap<String, AutoCloseDataSetLock> writeLockMap = new HashMap<>();
382	+
383	+    public synchronized void addLock(String name, ReentrantReadWriteLock lock) {
384	+      AutoCloseDataSetLock readLock = new AutoCloseDataSetLock(lock.readLock());
385	+      AutoCloseDataSetLock writeLock = new AutoCloseDataSetLock(lock.writeLock());
386	+      if (openLockTrace) {
387	+        readLock.setDataNodeLockManager(DataSetLockManager.this);
388	+        writeLock.setDataNodeLockManager(DataSetLockManager.this);
389	+      }
390	+      readlockMap.putIfAbsent(name, readLock);
391	+      writeLockMap.putIfAbsent(name, writeLock);
392	+    }
393	+
394	+    public synchronized void removeLock(String name) {
395	+      if (!readlockMap.containsKey(name) || !writeLockMap.containsKey(name)) {
396	+        LOG.error("The lock " + name + " is not in LockMap");
397	+      }
398	+      readlockMap.remove(name);
399	+      writeLockMap.remove(name);
400	+    }
401	+
402	+    public synchronized AutoCloseDataSetLock getReadLock(String name) {
403	+      return readlockMap.get(name);
404	+    }
405	+
406	+    public synchronized AutoCloseDataSetLock getWriteLock(String name) {
407	+      return writeLockMap.get(name);
408	+    }
409	+  }
