412	+   * Generate lock order string concatenates with lock name.
413	+   * @param level which level lock want to acquire.
414	+   * @param resources lock name by lock order.
415	+   * @return lock order string concatenates with lock name.
416	+   */
417	+  private String generateLockName(LockLevel level, String... resources) {
418	+    if (resources.length == 1 && level == LockLevel.BLOCK_POOl) {
419	+      if (resources[0] == null) {
420	+        throw new IllegalArgumentException("acquire a null block pool lock");
421	+      }
422	+      return resources[0];
423	+    } else if (resources.length == 2 && level == LockLevel.VOLUME) {
424	+      if (resources[0] == null || resources[1] == null) {
425	+        throw new IllegalArgumentException("acquire a null bp lock : "
426	+            + resources[0] + "volume lock :" + resources[1]);
427	+      }
428	+      return resources[0] + resources[1];
429	+    } else {
430	+      throw new IllegalArgumentException("lock level do not match resource");
431	+    }
432	+  }
